// Old source list deliberately retains old IDs. Same original SHA is insufficient for fact actions.
const OLD_FILES=[{"id":"FIL-EFFB9834","name":"F0106-PD-rebar-original.pdf","sha256":"ae8b16439650526a5ef6e1975c852fa38c2ab4466cd73ab725a47bcb32a6b655","size":23871472,"stages":["PD"],"pageCount":139,"registeredAt":"2026-10-17T23:08:21.223Z","review":null},{"id":"FIL-4D91EF2A","name":"F0139-RD-rebar-original.pdf","sha256":"d59c225e75d1e0227f08869b31165bd93bf85ed4b1da005c3e86ebc27023b73f","size":2298875,"stages":["RD"],"pageCount":22,"registeredAt":"2026-10-17T23:08:21.504Z","review":null}] as SourceFileSummary[];
const items=()=>buildMatrixReviewWorklist(clone(REAL),clone(OLD_FILES));
const opt=(filter:'ALL'|'BOTH_STAGES'|'ONE_STAGE'|'NO_FACTS'='ALL',factsFirst=false)=>({filter,factsFirst});
const at=(n:number)=>{const item=items().find(v=>v.resultIndex===n);assert.ok(item);return item;};
const ids=(rows:MatrixReviewWorkItem[])=>rows.map(r=>r.resultIndex);
const render=(data:MatrixExecutionRead=clone(REAL),files:SourceFileSummary[]=clone(OLD_FILES),callbacks:{onSelect?:any;onSource?:any}={})=>renderToStaticMarkup(<MatrixReviewWorklist data={data} files={files} onSelect={callbacks.onSelect??(()=>{})} onSource={callbacks.onSource??(()=>{})}/>);
const factSummaries=(html:string)=>(html.match(/· фактов:/gu)||[]).length;
const buttonTags=(html:string)=>html.match(/<button\b[^>]*>/gu)||[];
function invalid(n:number,kind:'reference'|'rule'='reference'){const item=clone(at(n));item.key+=':invalid';item.resultIndex+=100;if(kind==='rule'){item.invalidRule=true;item.rule=null;}else{item.groups[0].kind='INVALID_REFERENCE';item.groups[0].facts=[];}return item;}
afterEach(()=>{vi.restoreAllMocks();vi.unstubAllGlobals();});

describe('actual saved T48 priorities are availability, never comparison readiness',()=>{
 it('keeps all63 refusals,2both/4one/57none/0invalid with immutable locators',()=>{const rows=items();assert.equal(rows.length,63);const counts={BOTH_STAGES:0,ONE_STAGE:0,NO_FACTS:0,INVALID:0};for(const item of rows)counts[matrixReviewAvailability(item)]++;assert.deepEqual(counts,{BOTH_STAGES:2,ONE_STAGE:4,NO_FACTS:57,INVALID:0});assert.equal(new Set(rows.map(r=>r.key)).size,63);assert.deepEqual(ids(rows),Array.from({length:63},(_,n)=>n));});
 it('classifies concrete7PD+1RD and rebar1PD+1RD equally BOTH_STAGES',()=>{const concrete=at(32),rebar=at(33);assert.deepEqual(concrete.groups.map(g=>g.facts.length),[7,1]);assert.deepEqual(rebar.groups.map(g=>g.facts.length),[1,1]);assert.equal(matrixReviewAvailability(concrete),'BOTH_STAGES');assert.equal(matrixReviewAvailability(rebar),'BOTH_STAGES');assert.equal(concrete.result.reasonCode,'AMBIGUOUS_FACTS');assert.equal(rebar.result.reasonCode,'ENTITY_SCOPE_UNVERIFIED');});
 it('one-stage rows retain the exact saved direction and no chosen counterpart',()=>{assert.deepEqual([3,4,13,35].map(n=>[n,at(n).groups.filter(g=>g.facts.length).map(g=>g.stage)]),[[3,['PD']],[4,['RD']],[13,['PD']],[35,['PD']]]);for(const n of [3,4,13,35])assert.equal(matrixReviewAvailability(at(n)),'ONE_STAGE');});
 it('file list cannot turn frozen fact availability into a source-authority score',()=>{const nofiles=buildMatrixReviewWorklist(clone(REAL),[]),old=items();assert.deepEqual(old.map(matrixReviewAvailability),nofiles.map(matrixReviewAvailability));for(const row of old)for(const group of row.groups)for(const fact of group.facts)assert.equal(matrixReviewFactSource(fact,OLD_FILES),undefined);});
 it('default ALL false preserves exact input order/key/index and does not choose a pair',()=>{const rows=items(),before=clone(rows),selected=selectMatrixReviewWork(rows,opt());assert.deepEqual(selected,rows);assert.deepEqual(rows,before);assert.equal(selected[32].key,rows[32].key);assert.equal(selected[32].resultIndex,32);assert.equal(selected[32].groups[0].facts.length,7);});
 it('facts-first uses2/1/0stage then original resultIndex, never totalfact count',()=>{const rows=items(),result=selectMatrixReviewWork(rows,opt('ALL',true));assert.deepEqual(ids(result).slice(0,6),[32,33,3,4,13,35]);assert.deepEqual(ids(result).slice(6),ids(rows).filter(n=>![32,33,3,4,13,35].includes(n)));assert.deepEqual(ids(rows),Array.from({length:63},(_,n)=>n));});
 it('ties sort by saved resultIndex even if caller input is reversed',()=>{const rows=[at(35),at(13),at(4),at(3),at(33),at(32)];assert.deepEqual(ids(selectMatrixReviewWork(rows,opt('ALL',true))),[32,33,3,4,13,35]);assert.deepEqual(ids(selectMatrixReviewWork(rows,opt())),[35,13,4,3,33,32]);});
 it('each ordinary filter has exact saved counts and original order',()=>{assert.deepEqual(ids(selectMatrixReviewWork(items(),opt('BOTH_STAGES'))),[32,33]);assert.deepEqual(ids(selectMatrixReviewWork(items(),opt('ONE_STAGE'))),[3,4,13,35]);assert.equal(selectMatrixReviewWork(items(),opt('NO_FACTS')).length,57);});
 it('filter/sort never changes execution fields, groups, source facts, keys or preferred rule',()=>{const rows=items(),before=clone(rows);for(const filter of ['ALL','BOTH_STAGES','ONE_STAGE','NO_FACTS']as const)for(const sort of [false,true]){const result=selectMatrixReviewWork(rows,opt(filter,sort));for(const row of result)assert.deepEqual(row,before.find(r=>r.key===row.key));}assert.deepEqual(rows,before);});
 it('injected invalid reference/rule have INVALID precedence even if other stage has facts',()=>{for(const row of [invalid(32),invalid(33,'rule')])assert.equal(matrixReviewAvailability(row),'INVALID');});
 it('invalid results remain visible under every filter without automatic substitution',()=>{const broken=invalid(32),badRule=invalid(33,'rule'),rows=[at(0),broken,at(3),at(32),badRule];for(const filter of ['ALL','BOTH_STAGES','ONE_STAGE','NO_FACTS']as const){const result=selectMatrixReviewWork(rows,opt(filter));assert.ok(result.some(r=>r.key===broken.key));assert.ok(result.some(r=>r.key===badRule.key));assert.equal(result.find(r=>r.key===broken.key)!.groups[0].kind,'INVALID_REFERENCE');assert.equal(result.find(r=>r.key===broken.key)!.groups[0].facts.length,0);}});
 it('invalid rows sort last, stable saved index, still visible',()=>{const a=invalid(33,'rule'),b=invalid(32),rows=[a,at(0),b,at(3),at(32)];assert.deepEqual(ids(selectMatrixReviewWork(rows,opt('ALL',true))),[32,3,0,132,133]);});
 it('an empty worklist stays empty for every filter/sort',()=>{for(const filter of ['ALL','BOTH_STAGES','ONE_STAGE','NO_FACTS']as const)for(const sort of [false,true])assert.deepEqual(selectMatrixReviewWork([],opt(filter,sort)),[]);});
});

describe('explicit original source choices do not infer stage, pair, approval or manifest membership',()=>{
 it('keeps safe unique ID+lowerhex64SHA in original input order',()=>{const files=clone(OLD_FILES);assert.deepEqual(matrixReviewSourceChoices(files),files);assert.deepEqual(matrixReviewSourceChoices([...files].reverse()),[...files].reverse());});
 it('rejects entire duplicate-ID group even if only one has a valid or matching SHA',()=>{const a=clone(OLD_FILES[0]),b=clone(OLD_FILES[1]);for(const extra of [clone(a),{...clone(a),sha256:'e'.repeat(64)},{...clone(a),sha256:'bad'}])assert.deepEqual(matrixReviewSourceChoices([a,b,extra]),[b]);});
 it('same SHA on two distinct safe IDs does not merge files or remap fact sources',()=>{const a=clone(OLD_FILES[0]),b={...clone(a),id:'OTHER-SOURCE'};assert.deepEqual(matrixReviewSourceChoices([a,b]),[a,b]);const fact=at(32).groups[0].facts[0];assert.equal(matrixReviewFactSource(fact,[a,b]),undefined);});
 it('rejects unsafe IDs and SHA forms without constructing navigation paths',()=>{const a=clone(OLD_FILES[0]);for(const id of ['', '../other','with space','а','x'.repeat(201)])assert.deepEqual(matrixReviewSourceChoices([{...a,id}]),[]);for(const sha256 of ['', 'f'.repeat(63),'f'.repeat(65),'F'.repeat(64),'g'.repeat(64)])assert.deepEqual(matrixReviewSourceChoices([{...a,sha256}]),[]);});
 it('safe ID boundary200 and unreviewed/stage-unresolved source remain selectable, not approved',()=>{const a={...clone(OLD_FILES[0]),id:'x'.repeat(200),stages:[],review:null};assert.deepEqual(matrixReviewSourceChoices([a]),[a]);});
 it('empty input stays empty; choices never mutate source records',()=>{assert.deepEqual(matrixReviewSourceChoices([]),[]);const files=clone(OLD_FILES),before=clone(files);matrixReviewSourceChoices(files);assert.deepEqual(files,before);});
});

describe('default all-visible SSR controls and one explicit source chooser',()=>{
 it('shows all63 original result summaries by default without priority hiding',()=>{const html=render();assert.equal(factSummaries(html),63);const codes=[...html.matchAll(/<summary>([A-Z][A-Z0-9]*-\d{3}) ·/gu)].map(m=>m[1]);assert.deepEqual(codes,REAL.execution.results.map(r=>r.parameterCode));});
 it('offers exact availability labels and optional facts-first checkbox, not confidence ranking',()=>{const html=render();for(const s of ['Наличие исходных фактов','Все результаты','Факты обеих стадий','Факты одной стадии','Без исходных фактов','Сначала с исходными фактами'])assert.ok(html.includes(s),s);assert.match(html,/<select\b/u);assert.match(html,/<input[^>]*type="checkbox"/u);assert.doesNotMatch(html,/Готово к сравнению|Высокая уверенность|Вероятное нарушение|Сопоставимая пара/u);});
 it('renders exactly one shared source chooser instead of one per missing group',()=>{const html=render();assert.equal((html.match(/<summary>Искать в исходных файлах<\/summary>/gu)||[]).length,1);for(const file of OLD_FILES){assert.ok(html.includes('Проверить источник: '+file.name));assert.ok(html.includes(file.sha256));}assert.equal((html.match(/Проверить источник: /gu)||[]).length,2);});
 it('preserves original missingfact/reason/manual-no-value warning after controls are added',()=>{const html=render();assert.match(html,/Причина сохранённого результата: AMBIGUOUS_FACTS/);assert.match(html,/Ручная привязка не создаёт отсутствующее значение/);assert.match(html,/Пара автоматически не выбрана/);assert.doesNotMatch(html,/Нарушений нет|NO_VIOLATION|Проверено автоматически/u);});
 it('old sameSHA files do not authorize any fact action in new T48 source IDs',()=>{const html=render(),tags=html.match(/<button[^>]*>Открыть факт и правило<\/button>/gu)||[];assert.ok(tags.length>0);assert.ok(tags.every(tag=>tag.includes('disabled')));});
 it('invalid saved contentHash never enables fact or generic source actions',()=>{const data=clone(REAL);data.contentHash='invalid';const html=render(data);assert.ok(buttonTags(html).every(tag=>tag.includes('disabled')));});
 it('missing/unsafe check locator never enables generic source actions',()=>{for(const checkId of ['', '../foreign-check','unsafe check']){const data=clone(REAL);data.checkId=checkId;const html=render(data);assert.ok(buttonTags(html).every(tag=>tag.includes('disabled')));}});
 it('duplicate/unsafe file choices cannot create generic source buttons',()=>{const files=[...clone(OLD_FILES),clone(OLD_FILES[0]),{...clone(OLD_FILES[1]),id:'../unsafe'}];const html=render(clone(REAL),files);assert.ok(!html.includes('Проверить источник: '+OLD_FILES[0].name));assert.equal((html.match(/Проверить источник: /gu)||[]).length,1);});
 it('SSR never fetches, mutates input or invokes automatic source/fact callbacks',()=>{const fetch=vi.fn(()=>{throw new Error('unexpected fetch');});vi.stubGlobal('fetch',fetch);const onSelect=vi.fn(),onSource=vi.fn(),data=clone(REAL),files=clone(OLD_FILES),before=clone([data,files]);const html=render(data,files,{onSelect,onSource});assert.equal(fetch.mock.calls.length,0);assert.equal(onSelect.mock.calls.length,0);assert.equal(onSource.mock.calls.length,0);assert.deepEqual([data,files],before);assert.ok(buttonTags(html).every(tag=>/type="button"/u.test(tag)));assert.doesNotMatch(html,/<form\b|<img\b|<iframe\b/u);});
});
